import pandas as pd

def clean(df):
    df = df.copy()
    # Fix label variants (typos) in Category
    df['Category'] = df['Category'].replace({
        'Office Suplies': 'Office Supplies',
        'Furnture': 'Furniture'
    })
    # Remove exact duplicate rows (e.g., duplicate Order_ID 2005)
    df = df.drop_duplicates()
    return df

def answer(df):
    df = clean(df)
    result = {}
    grouped = df.groupby('Category')['Price'].mean()
    for category, value in grouped.items():
        if pd.notna(category):
            result[category] = value
    return result
